(function(){
"use strict";
if(window.ApascentarProfile)return;
var KEY="apascentar.profile.v1";
var people=[{"id":"maria","name":"Maria"},{"id":"noe","name":"Noé"},{"id":"pedro","name":"Pedro"},{"id":"rute","name":"Rute"},{"id":"daniel","name":"Daniel"},{"id":"jesus","name":"Jesus"},{"id":"davi","name":"Davi"},{"id":"moises","name":"Moisés"},{"id":"abraao","name":"Abraão"},{"id":"paulo","name":"Paulo"},{"id":"jose","name":"José"},{"id":"josue","name":"Josué"},{"id":"ester","name":"Ester"},{"id":"debora","name":"Débora"},{"id":"elias","name":"Elias"},{"id":"golias","name":"Golias"},{"id":"arao","name":"Arão"},{"id":"sansao","name":"Sansão"}];

var portraits={"maria":"data:image/png;base64,","noe":"data:image/png;base64,","pedro":"data:image/png;base64,","rute":"data:image/png;base64,","daniel":"data:image/png;base64,","jesus":"data:image/png;base64,","davi":"data:image/png;base64,","moises":"data:image/png;base64,","abraao":"data:image/png;base64,","paulo":"data:image/png;base64,","jose":"data:image/png;base64,","josue":"data:image/png;base64,","ester":"data:image/png;base64,","debora":"data:image/png;base64,","elias":"data:image/png;base64,","golias":"data:image/png;base64,","arao":"data:image/png;base64,","sansao":"data:image/png;base64,"};
var root,form,input,grid,submit,error,cancel,launcher,selected="",editing=false,priorFocus=null;
function normalize(n){return String(n||"").replace(/[\u0000-\u001f\u007f]/g,"").trim().slice(0,40);}
function person(id){return people.find(function(p){return p.id===id;});}
function read(){try{var p=JSON.parse(localStorage.getItem(KEY)||"null");return p&&typeof p.name==="string"&&normalize(p.name)&&person(p.avatar)?{version:1,name:normalize(p.name),avatar:p.avatar}:null;}catch(e){return null;}}
function avatar(p){return '<img class="ap-approved-portrait" src="'+portraits[p.id]+'" alt="'+p.name+'" width="94" height="92" decoding="async" draggable="false">';}
function update(){submit.disabled=!(normalize(input.value)&&person(selected));Array.prototype.forEach.call(grid.children,function(b){b.setAttribute("aria-checked",String(b.dataset.avatar===selected));});}
function show(edit){editing=!!edit;var p=read();priorFocus=document.activeElement;selected=p?p.avatar:"";input.value=p?p.name:"";submit.textContent=editing?"Salvar meu perfil":"Começar minha jornada";cancel.hidden=!(editing&&p);error.textContent="";root.hidden=false;launcher.hidden=true;document.body.style.overflow="hidden";update();input.focus();}
function close(){root.hidden=true;document.body.style.overflow="";refresh();if(priorFocus&&priorFocus.focus)priorFocus.focus();}
function refresh(){var p=read();launcher.hidden=!p;if(p){launcher.innerHTML=avatar(person(p.avatar))+"<span>Meu perfil</span>";launcher.setAttribute("aria-label","Meu perfil: "+p.name);}}
function ready(){
try{
root=document.createElement("section");root.id="ap-entry-root";root.setAttribute("role","dialog");root.setAttribute("aria-modal","true");root.setAttribute("aria-labelledby","ap-entry-title");root.hidden=true;root.innerHTML="<div class=\"ap-entry-wrap\"><img class=\"ap-entry-art\" src=\"approved-home/jesus-ovelha-principal.jpg\" alt=\"Jesus com uma ovelha\"><h1 id=\"ap-entry-title\">Bem-vindo ao Apascentar</h1><p class=\"ap-entry-intro\">Sua caminhada de fé começa aqui.</p><form><label for=\"ap-entry-name\">Como você se chama?</label><input id=\"ap-entry-name\" class=\"ap-entry-name\" name=\"name\" type=\"text\" maxlength=\"40\" autocomplete=\"given-name\" required><fieldset><legend>Escolha seu personagem</legend><div class=\"ap-entry-avatars\" role=\"radiogroup\" aria-label=\"Personagem do perfil\"></div></fieldset><p class=\"ap-entry-error\" role=\"alert\"></p><button class=\"ap-entry-submit\" type=\"submit\" disabled>Começar minha jornada</button><button class=\"ap-entry-cancel\" type=\"button\" hidden>Cancelar</button></form><p class=\"ap-entry-foot\">Seu perfil fica salvo somente neste aparelho. Sem e-mail e sem senha.</p></div>";
document.body.appendChild(root);form=root.querySelector("form");input=root.querySelector("input");grid=root.querySelector(".ap-entry-avatars");submit=root.querySelector(".ap-entry-submit");error=root.querySelector(".ap-entry-error");cancel=root.querySelector(".ap-entry-cancel");
people.forEach(function(p){var b=document.createElement("button");b.type="button";b.className="ap-entry-avatar";b.dataset.avatar=p.id;b.setAttribute("role","radio");b.setAttribute("aria-checked","false");b.innerHTML=avatar(p);var n=document.createElement("span");n.textContent=p.name;b.appendChild(n);b.addEventListener("click",function(){selected=p.id;update();});b.addEventListener("keydown",function(e){var keys=["ArrowRight","ArrowDown","ArrowLeft","ArrowUp"];if(keys.indexOf(e.key)<0)return;e.preventDefault();var list=Array.prototype.slice.call(grid.children),i=list.indexOf(b),delta=e.key==="ArrowLeft"||e.key==="ArrowUp"?-1:1;var next=list[(i+delta+list.length)%list.length];selected=next.dataset.avatar;update();next.focus();});grid.appendChild(b);});
launcher=document.createElement("button");launcher.id="ap-profile-open";launcher.type="button";launcher.addEventListener("click",function(){show(true);});document.body.appendChild(launcher);
input.addEventListener("input",update);cancel.addEventListener("click",close);
form.addEventListener("submit",function(e){e.preventDefault();var name=normalize(input.value);if(!name||!person(selected))return;var p={version:1,name:name,avatar:selected};try{localStorage.setItem(KEY,JSON.stringify(p));if(!read())throw new Error("storage");}catch(ex){error.textContent="Não foi possível salvar seu perfil neste aparelho. Tente novamente.";return;}close();window.dispatchEvent(new CustomEvent("apascentar:profile",{detail:p}));});
root.addEventListener("keydown",function(e){if(e.key==="Escape"&&editing){e.preventDefault();close();}if(e.key==="Tab"){var focus=Array.prototype.slice.call(root.querySelectorAll("input,button:not([disabled]):not([hidden])")),a=focus[0],b=focus[focus.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}});
window.ApascentarProfile={read:read,open:function(){show(!!read());},key:KEY,characters:people.map(function(p){return{id:p.id,name:p.name};})};
if(read())refresh();else show(false);
}catch(ex){console.error("Apascentar profile initialization failed",ex);}finally{document.documentElement.classList.remove("ap-entry-pending");}}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",ready,{once:true});else ready();
})();
